from collections import defaultdict

class Solution:
    def minOperations(self, source: str, target: str) -> int:
        if len(source) != len(target):
            return -1

        count = defaultdict(int)
        total_mismatches = 0
        for s, t in zip(source, target):
            if s != t:
                count[(s, t)] += 1
                total_mismatches += 1

        saved = 0
        chars = list(set([u for u, v in count.keys()] + [v for u, v in count.keys()]))

        # 2-cycles
        for i in range(len(chars)):
            for j in range(i + 1, len(chars)):
                u, v = chars[i], chars[j]
                k = min(count[(u, v)], count[(v, u)])
                saved += k
                count[(u, v)] -= k
                count[(v, u)] -= k

        # 3-cycles
        for i in range(len(chars)):
            for j in range(len(chars)):
                if i == j: continue
                for m in range(len(chars)):
                    if m == i or m == j: continue
                    u, v, w = chars[i], chars[j], chars[m]
                    k = min(count[(u, v)], count[(v, w)], count[(w, u)])
                    if k > 0:
                        saved += k
                        count[(u, v)] -= k
                        count[(v, w)] -= k
                        count[(w, u)] -= k

        return total_mismatches - saved

#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    int minOperations(std::string source, std::string target) {
        if (source.size() != target.size()) return -1;
        int n = source.size();

        int count[26][26] = {0};
        int total = 0;
        for (int i = 0; i < n; ++i) {
            if (source[i] != target[i]) {
                count[source[i] - 'a'][target[i] - 'a']++;
                total++;
            }
        }

        int saved = 0;
        for (int i = 0; i < 26; ++i) {
            for (int j = i + 1; j < 26; ++j) {
                int k = std::min(count[i][j], count[j][i]);
                saved += k;
                count[i][j] -= k;
                count[j][i] -= k;
            }
        }

        for (int i = 0; i < 26; ++i) {
            for (int j = 0; j < 26; ++j) {
                if (i == j) continue;
                for (int m = 0; m < 26; ++m) {
                    if (m == i || m == j) continue;
                    int k = std::min({count[i][j], count[j][m], count[m][i]});
                    if (k > 0) {
                        saved += k;
                        count[i][j] -= k;
                        count[j][m] -= k;
                        count[m][i] -= k;
                    }
                }
            }
        }

        return total - saved;
    }
};

class Solution {
    public int minOperations(String source, String target) {
        if (source.length() != target.length()) return -1;
        int n = source.length();

        int[][] count = new int[26][26];
        int total = 0;
        for (int i = 0; i < n; i++) {
            char s = source.charAt(i), t = target.charAt(i);
            if (s != t) {
                count[s - 'a'][t - 'a']++;
                total++;
            }
        }

        int saved = 0;
        for (int i = 0; i < 26; i++) {
            for (int j = i + 1; j < 26; j++) {
                int k = Math.min(count[i][j], count[j][i]);
                saved += k;
                count[i][j] -= k;
                count[j][i] -= k;
            }
        }

        for (int i = 0; i < 26; i++) {
            for (int j = 0; j < 26; j++) {
                if (i == j) continue;
                for (int m = 0; m < 26; m++) {
                    if (m == i || m == j) continue;
                    int k = Math.min(count[i][j], Math.min(count[j][m], count[m][i]));
                    if (k > 0) {
                        saved += k;
                        count[i][j] -= k;
                        count[j][m] -= k;
                        count[m][i] -= k;
                    }
                }
            }
        }

        return total - saved;
    }
}

