var minOperations = function(source, target) {
    if (source.length !== target.length) return -1;
    const n = source.length;

    const count = Array.from({ length: 26 }, () => new Int32Array(26));
    let total = 0;
    for (let i = 0; i < n; i++) {
        const s = source.charCodeAt(i) - 97;
        const t = target.charCodeAt(i) - 97;
        if (s !== t) {
            count[s][t]++;
            total++;
        }
    }

    let saved = 0;
    for (let i = 0; i < 26; i++) {
        for (let j = i + 1; j < 26; j++) {
            const k = Math.min(count[i][j], count[j][i]);
            saved += k;
            count[i][j] -= k;
            count[j][i] -= k;
        }
    }

    for (let i = 0; i < 26; i++) {
        for (let j = 0; j < 26; j++) {
            if (i === j) continue;
            for (let m = 0; m < 26; m++) {
                if (m === i || m === j) continue;
                const k = Math.min(count[i][j], count[j][m], count[m][i]);
                if (k > 0) {
                    saved += k;
                    count[i][j] -= k;
                    count[j][m] -= k;
                    count[m][i] -= k;
                }
            }
        }
    }

    return total - saved;
};
